# SOLUTION_SOURCE: required
# synthetic unittests
import unittest
import ast
__solution_source__ = ""
def _qsp_operation_is_appended(data, obj):
    import builtins
    return builtins.any(instr.operation is obj for instr in data)


def _qsp_power_then_control_chain(
    base_module, base_name, exponent, num_ctrl, var_name, solution_source
):
    import builtins as _builtins
    import importlib as _importlib
    from qiskit.circuit.gate import Gate
    from qiskit.circuit.library.generalized_gates.unitary import UnitaryGate
    _base_cls = _builtins.getattr(
        _importlib.import_module(base_module), base_name
    )
    _power_calls = []
    _control_calls = []
    _orig_power = Gate.power
    _orig_control = UnitaryGate.control

    def _patched_power(self, *args, **kwargs):
        _exp = args[0] if args else kwargs.get('exponent')
        _result = _orig_power(self, *args, **kwargs)
        _power_calls.append((self, _exp, _result))
        return _result

    def _patched_control(self, *args, **kwargs):
        _n = args[0] if args else kwargs.get('num_ctrl_qubits', 1)
        _result = _orig_control(self, *args, **kwargs)
        _control_calls.append((self, _n, _result))
        return _result

    _ns = {}
    _builtins.setattr(Gate, 'power', _patched_power)
    _builtins.setattr(UnitaryGate, 'control', _patched_control)
    try:
        _builtins.exec(
            _builtins.compile(solution_source, '<solution>', 'exec'), _ns
        )
    finally:
        _builtins.setattr(Gate, 'power', _orig_power)
        _builtins.setattr(UnitaryGate, 'control', _orig_control)
    _target = _ns.get(var_name)
    for _recv1, _exp1, _res1 in _power_calls:
        if _exp1 != exponent or not _builtins.isinstance(_recv1, _base_cls):
            continue
        for _recv2, _n2, _res2 in _control_calls:
            if _recv2 is _res1 and _n2 == num_ctrl and _res2 is _target:
                return True
    return False


class LLMGenTest(unittest.TestCase):

    def test_gate_inverse_power__VarGateInversePower_0_gate_power_control_instruction_count(self):
        assert len(qc.data) == 2, 'qc must have exactly two instructions.'

    def test_gate_inverse_power__VarGateInversePower_0_gate_power_control_var_appended(self):
        assert _qsp_operation_is_appended(qc.data, controlled_power_gate) == True, 'controlled_power_gate must itself be one of the instructions appended to qc, not a separately hand-built equivalent.'

    def test_gate_inverse_power__VarGateInversePower_0_gate_power_control_var_qubit_placement(self):
        assert [qc.find_bit(q).index for instr in qc.data if instr.operation is controlled_power_gate for q in instr.qubits] == [1, 2], 'controlled_power_gate must be applied to exactly qubits [1, 2] (control qubits followed by the target qubit) in qc, not any other placement.'

    def test_gate_inverse_power__VarGateInversePower_0_gate_power_control_chain_provenance(self):
        assert _qsp_power_then_control_chain('qiskit.circuit.library', 'YGate', 0.5, 1, 'controlled_power_gate', __solution_source__) == True, 'controlled_power_gate must be the result of a genuine chain -- raising the Pauli-Y gate to the 0.5 power, then calling .control(1) on that exact resulting operation -- not a hand-built stand-in or a disconnected chain built elsewhere purely to satisfy this check.'

    def test_unitary_equiv_qc(self):  # reward: 1.0
        from qiskit.circuit import QuantumCircuit
        from qiskit.quantum_info import Operator
        ref = QuantumCircuit(3)
        from qiskit.circuit.library import YGate
        ref.append(YGate().power(0.5).control(1), [1, 2])
        ref.rz(0.8, 0)
        self.assertTrue(
            Operator(qc).equiv(Operator(ref)),
            msg="Circuit unitary does not match the reference unitary",
        )

    def test_required_calls(self):  # reward: 1.0
        tree = ast.parse(__solution_source__)
        required = ['power', 'control']
