        def _assign_targets(n):
            if isinstance(n, ast.Assign):
                return [t for t in n.targets if isinstance(t, ast.Name)]
            if isinstance(n, ast.AnnAssign) and isinstance(n.target, ast.Name):
                return [n.target]
            return []

        def _class_before(var_name, line, col):
            result = None
            for _assign_node in _assigns:
                if (_assign_node.end_lineno, _assign_node.end_col_offset) > (
                    line,
                    col,
                ):
                    break
                if not _builtins.any(
                    t.id == var_name for t in _assign_targets(_assign_node)
                ):
                    continue
                if (
                    isinstance(_assign_node.value, ast.Name)
                    and _assign_node.value.id == var_name
                ):
                    continue
                result = (
                    _callee_name(_assign_node.value)
                    if isinstance(_assign_node.value, ast.Call)
                    else None
                )
            return result

