def _qsp_power_chain_roundtrip(
    base_module, base_name, exponents, var_name, solution_source
):
    import builtins as _builtins
    import importlib as _importlib
    from qiskit.circuit.library.standard_gates.p import PhaseGate
    _base_cls = _builtins.getattr(
        _importlib.import_module(base_module), base_name
    )
    _calls = []
    _orig_base_power = _base_cls.power
    _orig_phase_power = PhaseGate.power

    def _qsp_make_patched_power(_orig):
        def _patched_power(self, *args, **kwargs):
            _exp = args[0] if args else kwargs.get('exponent')
            _result = _orig(self, *args, **kwargs)
            _calls.append((self, _exp, _result))
            return _result

        return _patched_power

    _ns = {}
    _builtins.setattr(
        _base_cls, 'power', _qsp_make_patched_power(_orig_base_power)
    )
    _builtins.setattr(
        PhaseGate, 'power', _qsp_make_patched_power(_orig_phase_power)
    )
    try:
        _builtins.exec(
            _builtins.compile(solution_source, '<solution>', 'exec'), _ns
        )
    finally:
        _builtins.setattr(_base_cls, 'power', _orig_base_power)
        _builtins.setattr(PhaseGate, 'power', _orig_phase_power)
    _target = _ns.get(var_name)
    for _recv1, _exp1, _res1 in _calls:
        if _exp1 != exponents[0] or not _builtins.isinstance(_recv1, _base_cls):
            continue
        for _recv2, _exp2, _res2 in _calls:
            if _recv2 is _res1 and _exp2 == exponents[1] and _res2 is _target:
                return True
    return False


