    def test_runtime_provenance_oracle_522_grover_operator_arg(self):  # reward: 1.0
        import importlib as _qsp_importlib
        import sys as _qsp_sys
        import builtins as _builtins
        _qsp_mod = _qsp_importlib.import_module('qiskit.circuit.library')
        _qsp_orig = getattr(_qsp_mod, 'grover_operator')
        _qsp_targets = [(_qsp_mod, 'grover_operator')]
        _qsp_seen = {_builtins.id(_qsp_mod)}
        _qsp_defmod_name = getattr(_qsp_orig, '__module__', None) or ''
        _qsp_parts = _qsp_defmod_name.split('.') if _qsp_defmod_name else []
        for _qsp_i in _builtins.range(1, _builtins.len(_qsp_parts) + 1):
            try:
                _qsp_cand = _qsp_importlib.import_module('.'.join(_qsp_parts[:_qsp_i]))
            except ImportError:
                continue
            if _builtins.id(_qsp_cand) in _qsp_seen:
                continue
            _qsp_seen.add(_builtins.id(_qsp_cand))
            if getattr(_qsp_cand, 'grover_operator', None) is _qsp_orig:
                _qsp_targets.append((_qsp_cand, 'grover_operator'))

        _qsp_registry = []
        import inspect as _qsp_inspect
        _qsp_sig = _qsp_inspect.signature(_qsp_orig)

        def _qsp_safe_copy(_qsp_sc_val):
            _qsp_sc_t = _builtins.type(_qsp_sc_val)
            if _qsp_sc_t in (
                _builtins.int,
                _builtins.float,
                _builtins.complex,
                _builtins.str,
                _builtins.bytes,
                _builtins.bool,
                _builtins.type(None),
            ):
                return _qsp_sc_val
            if _qsp_sc_t is _builtins.dict:
                return {
                    _qsp_safe_copy(_qsp_sc_k): _qsp_safe_copy(_qsp_sc_v)
                    for _qsp_sc_k, _qsp_sc_v in _qsp_sc_val.items()
                }
            if _qsp_sc_t is _builtins.list:
                return [_qsp_safe_copy(_qsp_sc_x) for _qsp_sc_x in _qsp_sc_val]
            if _qsp_sc_t is _builtins.tuple:
                return _builtins.tuple(
                    _qsp_safe_copy(_qsp_sc_x) for _qsp_sc_x in _qsp_sc_val
                )
            if _qsp_sc_t is _builtins.set:
                return {_qsp_safe_copy(_qsp_sc_x) for _qsp_sc_x in _qsp_sc_val}
            if _qsp_sc_t is _builtins.frozenset:
                return _builtins.frozenset(
                    _qsp_safe_copy(_qsp_sc_x) for _qsp_sc_x in _qsp_sc_val
                )
            # Any other type -- including a subclass of a builtin
            # container -- is treated as an opaque leaf and stored BY
            # REFERENCE, WITHOUT invoking `__deepcopy__`/`__copy__`/
            # `__reduce__` on it. Those are solution-defined hooks: a
            # hostile solution could pass a decoy object whose
            # `__deepcopy__` reports a fake 'copy' equal to the graded
            # variable while the REAL object handed to the wrapped
            # function is something else entirely, spoofing this very
            # provenance snapshot. Recursing only through exact
            # builtin container types (never a subclass, and never by
            # calling the object's own methods) closes that hook while
            # still deep-copying the common plain dict/list/tuple/
            # set/frozenset case the snapshot needs to survive.
            return _qsp_sc_val

        def _qsp_pe_key(_qsp_pe_x):
            _qsp_pe_xt = _builtins.type(_qsp_pe_x)
            if _qsp_pe_xt in (
                _builtins.int,
                _builtins.float,
                _builtins.complex,
                _builtins.str,
                _builtins.bytes,
                _builtins.bool,
                _builtins.type(None),
            ):
                # Tag with the EXACT type alongside the value -- see
                # the matching comment in `_qsp_prov_eq` below.
                return (_qsp_pe_xt, _qsp_pe_x)
            if _qsp_pe_xt is _builtins.tuple:
                return (
                    _builtins.tuple,
                    _builtins.tuple(_qsp_pe_key(_qsp_pe_e) for _qsp_pe_e in _qsp_pe_x),
                )
            if _qsp_pe_xt is _builtins.frozenset:
                return (
                    _builtins.frozenset,
                    _builtins.frozenset(_qsp_pe_key(_qsp_pe_e) for _qsp_pe_e in _qsp_pe_x),
                )
            # `_builtins.id`, not bare `id` -- see the matching
            # comment in the other `_qsp_pe_key` copy above.
            return _builtins.id(_qsp_pe_x)

        def _qsp_prov_eq(_qsp_pe_a, _qsp_pe_b):
            # Structural comparator mirroring `_qsp_safe_copy`'s own
            # recursion boundary: only exact builtin container types
            # are compared structurally; anything else (an opaque
            # leaf stored by reference, e.g. a QuantumCircuit, or --
            # the whole reason this function exists instead of a
            # plain `==` -- a hostile subclass with a spoofed
            # `__eq__`) is compared by IDENTITY. A plain `==` here
            # would let a solution pass e.g. a `dict` subclass
            # instance whose `__eq__` unconditionally returns True,
            # wrongly matching `_qsp_obj` regardless of the actual
            # argument content the wrapped consumer received.
            _qsp_pe_ta, _qsp_pe_tb = _builtins.type(_qsp_pe_a), _builtins.type(_qsp_pe_b)
            _qsp_pe_seq_types = (_builtins.list, _builtins.tuple)
            _qsp_pe_uset_types = (_builtins.set, _builtins.frozenset)
            _qsp_pe_same_family = (
                _qsp_pe_ta in _qsp_pe_seq_types and _qsp_pe_tb in _qsp_pe_seq_types
            ) or (
                _qsp_pe_ta in _qsp_pe_uset_types and _qsp_pe_tb in _qsp_pe_uset_types
            )
            if not _qsp_pe_same_family and _qsp_pe_ta is not _qsp_pe_tb:
                return False
            if _qsp_pe_ta in (
                _builtins.int,
                _builtins.float,
                _builtins.complex,
                _builtins.str,
                _builtins.bytes,
                _builtins.bool,
                _builtins.type(None),
            ):
                return _qsp_pe_a == _qsp_pe_b
            if _qsp_pe_ta is _builtins.dict:
                _qsp_pe_av = {
                    _qsp_pe_key(_qsp_pe_k): _qsp_pe_v
                    for _qsp_pe_k, _qsp_pe_v in _qsp_pe_a.items()
                }
                _qsp_pe_bv = {
                    _qsp_pe_key(_qsp_pe_k): _qsp_pe_v
                    for _qsp_pe_k, _qsp_pe_v in _qsp_pe_b.items()
                }
                return _qsp_pe_av.keys() == _qsp_pe_bv.keys() and _builtins.all(
                    _qsp_prov_eq(_qsp_pe_v, _qsp_pe_bv[_qsp_pe_tk])
                    for _qsp_pe_tk, _qsp_pe_v in _qsp_pe_av.items()
                )
            if _qsp_pe_ta in (_builtins.list, _builtins.tuple):
                return _builtins.len(_qsp_pe_a) == _builtins.len(
                    _qsp_pe_b
                ) and _builtins.all(
                    _qsp_prov_eq(_qsp_pe_x, _qsp_pe_y)
                    for _qsp_pe_x, _qsp_pe_y in _builtins.zip(_qsp_pe_a, _qsp_pe_b)
                )
            if _qsp_pe_ta in (_builtins.set, _builtins.frozenset):
                return {_qsp_pe_key(_qsp_pe_x) for _qsp_pe_x in _qsp_pe_a} == {
                    _qsp_pe_key(_qsp_pe_x) for _qsp_pe_x in _qsp_pe_b
                }
            return _qsp_pe_a is _qsp_pe_b

        def _qsp_wrapped(*_qsp_a, **_qsp_k):
            _qsp_caller = _qsp_sys._getframe(1)
            if _qsp_caller.f_code.co_filename == '<solution>':
                try:
                    _qsp_bound = _qsp_sig.bind(*_qsp_a, **_qsp_k)
                    _qsp_bound.apply_defaults()
                except TypeError:
                    pass
                else:
                    # Snapshot via _qsp_safe_copy BEFORE calling the
                    # wrapped function (not a bare dict() of the bound
                    # arguments taken after the call returns) -- a
                    # plain mutable argument (e.g. a dict/list) is
                    # otherwise stored BY REFERENCE, so if the wrapped
                    # (real) function mutates its own argument in place
                    # as a side effect, a post-call snapshot would
                    # record the POST-mutation state rather than what
                    # the solution actually passed, letting a decoy
                    # argument be laundered by the callee.
                    # `_qsp_safe_copy` (not `copy.deepcopy`) is used so
                    # this snapshot can never be spoofed by a
                    # solution-defined `__deepcopy__` hook.
                    _qsp_snapshot = _qsp_safe_copy(_builtins.dict(_qsp_bound.arguments))
                    _qsp_registry.append(_qsp_snapshot)
            return _qsp_orig(*_qsp_a, **_qsp_k)

        for _qsp_m, _qsp_n in _qsp_targets:
            setattr(_qsp_m, _qsp_n, _qsp_wrapped)
        try:
            _qsp_ns = {}
            exec(compile(__solution_source__, '<solution>', 'exec'), _qsp_ns)
            _qsp_obj = _qsp_ns.get('oracle_522')
            self.assertIsNotNone(
                _qsp_obj, msg='oracle_522' + ' was not defined by the solution.'
            )
            self.assertTrue(
                _builtins.any(
                    _qsp_prov_eq(_qsp_call.get('oracle'), _qsp_obj)
                    for _qsp_call in _qsp_registry
                ),
                msg="A call to grover_operator must receive oracle_522 (or an equal value) as its oracle argument.",
            )
        finally:
            for _qsp_m, _qsp_n in _qsp_targets:
                setattr(_qsp_m, _qsp_n, _qsp_orig)

