                    for _qsp_call in _qsp_registry
                ),
                msg="A call to grover_operator must receive oracle_396 (or an equal value) as its oracle argument.",
            )
        finally:
            for _qsp_m, _qsp_n in _qsp_targets:
                setattr(_qsp_m, _qsp_n, _qsp_orig)

