def _grover_strip_measurements(circuit):
    qc = circuit.copy()
    qc.remove_final_measurements(inplace=True)
    return qc


def _grover_success_probability(circuit, marked_bits):
    from qiskit.quantum_info import Statevector

    qc = _grover_strip_measurements(circuit)
    sv = Statevector(qc)
    return sv.probabilities_dict().get(marked_bits, 0.0)


def _grover_count_gate(circuit, name, max_depth=4):
    count = 0
    stack = [(circuit, 0)]
    while stack:
        circ, depth = stack.pop()
        for instr in circ.data:
            op = instr.operation
            if op.name == name:
                count += 1
                continue
            if depth < max_depth:
                try:
                    definition = op.definition
                except Exception:
                    definition = None
                if definition is not None:
                    stack.append((definition, depth + 1))
    return count


